pub fn validate_session(token: &SessionToken, now: Instant) -> Result<Session, AuthError> {
    if token.expires_at <= now {
        return Err(AuthError::SessionExpired);
    }
    if token.revoked {
        return Err(AuthError::Revoked);
    }
    Ok(token.session.clone())
}

pub fn is_session_valid(session: &Session, clock: &dyn Clock) -> bool {
    !session.invalidated && session.token_expiry > clock.now()
}

pub fn token_expiry(issued_at: DateTime<Utc>, ttl_secs: i64) -> DateTime<Utc> {
    issued_at + Duration::seconds(ttl_secs)
}

pub fn start_session(user_id: u64, ttl: Duration) -> Session {
    Session { user_id, created: Utc::now(), expires: Utc::now() + ttl, invalidated: false }
}

pub fn refresh_session(session: &mut Session, extra: Duration) {
    session.expires = Utc::now() + extra;
}

pub struct RetryPolicy { pub max_attempts: u32, pub base_delay: Duration, pub max_delay: Duration }
impl RetryPolicy {
    pub fn should_retry(&self, attempt: u32, status: u16) -> bool {
        attempt < self.max_attempts && (status == 429 || status >= 500)
    }
}

pub fn exponential_backoff(attempt: u32, base: Duration, max: Duration) -> Duration {
    let exp = base.mul_f64(2f64.powi(attempt as i32));
    let jitter = Duration::from_millis(rand_range(0, 50));
    exp.min(max) + jitter
}

pub fn request_attempt(client: &HttpClient, req: &Request, attempt: u32) -> Result<Response, HttpError> {
    let mut r = req.clone();
    r.headers.insert("X-Attempt", attempt.to_string());
    client.send(r)
}

pub fn retry_failed_request(client: &HttpClient, req: Request, policy: &RetryPolicy) -> Result<Response, HttpError> {
    let mut last = None;
    for attempt in 0..policy.max_attempts {
        match request_attempt(client, &req, attempt) {
            Ok(resp) if resp.status < 500 => return Ok(resp),
            Err(e) | Ok(_) => {
                last = Some(e.into());
                sleep(exponential_backoff(attempt, policy.base_delay, policy.max_delay));
            }
        }
    }
    Err(last.unwrap())
}

pub fn send_json<T: Serialize>(url: &str, body: &T) -> Result<Response, HttpError> {
    let client = HttpClient::new();
    client.post(url).json(body).send()
}

pub struct CircuitBreaker { failures: u32, threshold: u32, open_until: Instant }
impl CircuitBreaker {
    pub fn allow(&self, now: Instant) -> bool { now >= self.open_until && self.failures < self.threshold }
}

pub fn rollback_transaction(tx: Transaction) -> Result<(), DbError> {
    tx.execute("ROLLBACK").map(|_| ())
}

pub fn commit_transaction(tx: Transaction) -> Result<(), DbError> {
    tx.execute("COMMIT").map(|_| ())
}

pub fn begin_transaction(conn: &mut Connection) -> Result<Transaction, DbError> {
    conn.execute("BEGIN")?;
    Ok(Transaction { conn })
}

pub fn with_transaction<T>(conn: &mut Connection, f: impl FnOnce(&mut Transaction) -> Result<T, DbError>) -> Result<T, DbError> {
    let mut tx = begin_transaction(conn)?;
    match f(&mut tx) {
        Ok(v) => { commit_transaction(tx)?; Ok(v) }
        Err(e) => { let _ = rollback_transaction(tx); Err(e) }
    }
}

pub fn savepoint(tx: &Transaction, name: &str) -> Result<(), DbError> {
    tx.execute(&format!("SAVEPOINT {name}")).map(|_| ())
}

pub async fn jwt_validation_middleware(req: Request, next: Next) -> Response {
    let token = match bearer_token(&req) {
        Some(t) => t,
        None => return Response::unauthorized("missing bearer token"),
    };
    match decode_and_verify_jwt(token, &JWT_SECRET) {
        Ok(claims) => { req.extensions.insert(claims); next.run(req).await }
        Err(_) => Response::unauthorized("invalid jwt"),
    }
}

pub fn decode_and_verify_jwt(token: &str, secret: &[u8]) -> Result<Claims, JwtError> {
    let (header, payload, sig) = split_jwt(token)?;
    verify_signature(header, payload, sig, secret)?;
    let claims: Claims = serde_json::from_slice(&b64decode(payload)?)?;
    if claims.exp < now_unix() { return Err(JwtError::Expired); }
    Ok(claims)
}

pub fn verify_signature(header: &str, payload: &str, sig: &[u8], secret: &[u8]) -> Result<(), JwtError> {
    let mac = hmac_sha256(secret, format!("{header}.{payload}").as_bytes());
    if !constant_time_eq(&mac, sig) { Err(JwtError::BadSignature) } else { Ok(()) }
}

pub fn issue_jwt(user_id: u64, secret: &[u8], ttl: i64) -> String {
    let claims = Claims { sub: user_id, exp: now_unix() + ttl };
    sign_jwt(&claims, secret)
}

pub fn hash_password(plain: &str) -> Result<String, CryptoError> {
    let salt = generate_salt();
    bcrypt::hash_with_salt(plain, bcrypt::DEFAULT_COST, &salt).map(|h| h.to_string())
}

pub fn verify_bcrypt(plain: &str, hashed: &str) -> bool {
    bcrypt::verify(plain, hashed).unwrap_or(false)
}

pub fn generate_salt() -> [u8; 16] {
    let mut s = [0u8; 16];
    getrandom::getrandom(&mut s).expect("rng");
    s
}

pub fn check_permission(user: &User, action: &str, resource: &str) -> bool {
    user.roles.iter().any(|role| role.allows(action, resource))
}

pub struct RbacPolicy { pub roles: Vec<Role> }
impl RbacPolicy {
    pub fn is_allowed(&self, role: &str, action: &str) -> bool {
        self.roles.iter().any(|r| r.name == role && r.actions.contains(&action.to_string()))
    }
}

pub fn is_admin(user: &User) -> bool {
    user.roles.iter().any(|r| r.name == "admin")
}

pub fn lru_evict<K, V>(cache: &mut LruCache<K, V>) -> Option<(K, V)> {
    cache.pop_lru()
}

pub fn invalidate_cache(redis: &mut Redis, key: &str) -> Result<(), CacheError> {
    redis.del(key).map(|_| ())
}

pub fn cache_get(redis: &Redis, key: &str) -> Option<Vec<u8>> {
    redis.get(key).ok().flatten()
}

pub fn cache_set(redis: &mut Redis, key: &str, val: &[u8], ttl: Duration) -> Result<(), CacheError> {
    redis.set_ex(key, val, ttl.as_secs()).map(|_| ())
}

pub fn enqueue_job(q: &Queue, job: Job) -> Result<JobId, QueueError> {
    q.push(job)
}

pub fn dead_letter(q: &Queue, job: Job, err: &str) {
    q.dead_letter.push(DeadLetter { job, err: err.into(), at: Utc::now() });
}

pub fn worker_loop(q: &Queue, handler: impl Fn(Job) -> Result<(), String>) {
    while let Some(job) = q.pop() {
        if let Err(e) = handler(job.clone()) {
            if job.attempts >= job.max_attempts { dead_letter(q, job, &e); }
            else { q.retry(job); }
        }
    }
}

pub fn upload_file(store: &BlobStore, name: &str, bytes: &[u8]) -> Result<BlobId, IoError> {
    store.put(name, bytes)
}

pub fn stream_download(store: &BlobStore, id: BlobId) -> impl Stream<Item = Result<Bytes, IoError>> {
