pub fn detect_mime_type(name: &str, prefix: &[u8]) -> &'static str {
    if prefix.starts_with(b"\x89PNG") { "image/png" }
    else if name.ends_with(".json") { "application/json" }
    else { "application/octet-stream" }
}

