    let bytes = b64decode(raw)?;
    serde_json::from_slice(&bytes).map_err(|_| ApiError::BadCursor)
}

pub fn encode_page_token(cursor: &PageCursor) -> String {
    b64encode(&serde_json::to_vec(cursor).unwrap())
}

pub fn send_welcome_email(to: &str, name: &str) -> Result<(), MailError> {
    let body = render_template("welcome", &[("name", name)]);?
    smtp_send(to, "Welcome", &body)
}

pub fn render_template(name: &str, vars: &[(&str, &str)]) -> Result<String, MailError> {
    let mut t = TEMPLATES.get(name).ok_or(MailError::Missing)?.to_string();
    for (k, v) in vars { t = t.replace(&format!("{{{{{k}}}}}"), v); }
    Ok(t)
}

pub struct TokenBucket { tokens: f64, rate: f64, burst: f64, last: Instant }
impl TokenBucket {
    pub fn allow(&mut self, now: Instant) -> bool {
        self.tokens = (self.tokens + (now - self.last).as_secs_f64() * self.rate).min(self.burst);
        self.last = now;
        if self.tokens >= 1.0 { self.tokens -= 1.0; true } else { false }
    }
}

pub fn too_many_requests(ip: IpAddr, buckets: &mut HashMap<IpAddr, TokenBucket>) -> bool {
    !buckets.entry(ip).or_insert_with(TokenBucket::default).allow(Instant::now())
}

pub fn broadcast_event(hub: &Hub, event: Event) {
    for sock in hub.subscribers() { let _ = sock.send(&event); }
}

pub fn subscribe_channel(hub: &mut Hub, channel: &str, sock: SocketId) {
    hub.channels.entry(channel.into()).or_default().insert(sock);
}

pub fn parse_search_query(q: &str) -> ParsedQuery {
    ParsedQuery { terms: q.split_whitespace().map(|t| t.to_lowercase()).collect() }
}

