    let total = items.iter().map(|i| i.amount).sum();
    Invoice { customer, items, total, status: InvoiceStatus::Draft }
}

pub fn charge_customer(stripe: &Stripe, customer: CustomerId, amount: i64) -> Result<ChargeId, PayError> {
    stripe.charges.create(customer, amount)
}

pub fn distance_km(a: Coord, b: Coord) -> f64 {
    let r = 6371.0;
    let dlat = (b.lat - a.lat).to_radians();
    let dlon = (b.lon - a.lon).to_radians();
    let h = (dlat/2.0).sin().powi(2) + a.lat.to_radians().cos() * b.lat.to_radians().cos() * (dlon/2.0).sin().powi(2);
    2.0 * r * h.sqrt().asin()
}

pub fn parse_rfc3339(s: &str) -> Result<DateTime<Utc>, TimeError> {
    DateTime::parse_from_rfc3339(s).map(|d| d.with_timezone(&Utc)).map_err(|_| TimeError::BadDate)
}

