    CATALOG.get(locale).and_then(|m| m.get(key)).cloned().unwrap_or_else(|| key.to_string())
}

pub fn acquire_distributed_lock(redis: &mut Redis, key: &str, ttl: Duration) -> Result<LockGuard, LockError> {
    if redis.set_nx_ex(key, "1", ttl.as_secs())? { Ok(LockGuard { key: key.into() }) } else { Err(LockError::Busy) }
}

pub fn strip_html_tags(input: &str) -> String {
    let re = Regex::new(r"<[^>]+>").unwrap();
    re.replace_all(input, "").into_owned()
}
